      'locations?: string[];',
      "shipment_changes?: { add?: { delivery: { id: string; location_index: number; description?: string; max_visit_lateness?: number; metadata?: object; sequence_order?: number; service?: number; setup?: number; time_windows?: number[][]; }; pickup: { id: string; location_index: number; description?: string; max_visit_lateness?: number; metadata?: object; sequence_order?: number; service?: number; setup?: number; time_windows?: number[][]; }; amount?: number[]; follow_lifo_order?: boolean; incompatible_load_types?: string[]; joint_order?: number; load_types?: string[]; max_time_in_vehicle?: number; outsourcing_cost?: number; priority?: number; revenue?: number; skills?: number[]; volume?: { alignment?: 'strict' | 'parallel' | 'fixed_bottom'; depth?: number; height?: number; width?: number; }; zones?: number[]; }[]; modify?: { delivery: { id: string; location_index: number; description?: string; max_visit_lateness?: number; metadata?: object; sequence_order?: number; service?: number; setup?: number; time_windows?: number[][]; }; pickup: { id: string; location_index: number; description?: string; max_visit_lateness?: number; metadata?: object; sequence_order?: number; service?: number; setup?: number; time_windows?: number[][]; }; amount?: number[]; follow_lifo_order?: boolean; incompatible_load_types?: string[]; joint_order?: number; load_types?: string[]; max_time_in_vehicle?: number; outsourcing_cost?: number; priority?: number; revenue?: number; skills?: number[]; volume?: { alignment?: 'strict' | 'parallel' | 'fixed_bottom'; depth?: number; height?: number; width?: number; }; zones?: number[]; }[]; remove?: string[]; };",
